import{j as a,b as l,c as i,ae as t}from"./chunks/framework.DkjvVb1g.js";const m=JSON.parse('{"title":"LLM 与 LLVM 基础面试题","description":"Agent 后端开发中常见的 LLM 基础问题，并补充 LLVM 编译器基础。","frontmatter":{"title":"LLM 与 LLVM 基础面试题","description":"Agent 后端开发中常见的 LLM 基础问题，并补充 LLVM 编译器基础。","date":"2026-06-11T00:00:00.000Z","tags":["LLM","LLVM","Agent"],"categories":["面经"]},"headers":[],"relativePath":"interview/agent-backend/llm-llvm-basics.md","filePath":"interview/agent-backend/llm-llvm-basics.md","lastUpdated":1782271370000}'),n={name:"interview/agent-backend/llm-llvm-basics.md"};function r(d,e,o,s,h,c){return l(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781136000000"},[...e[0]||(e[0]=[t('<h1 id="llm-与-llvm-基础面试题" tabindex="-1">LLM 与 LLVM 基础面试题 <a class="header-anchor" href="#llm-与-llvm-基础面试题" aria-label="Permalink to “LLM 与 LLVM 基础面试题”">​</a></h1><p>Agent 后端岗位通常重点考察 <code>LLM 基础</code>，但如果岗位涉及模型编译、推理优化、AI Infra，也可能问到 <code>LLVM</code>。本篇同时整理两部分。</p><h2 id="一、llm-基础" tabindex="-1">一、LLM 基础 <a class="header-anchor" href="#一、llm-基础" aria-label="Permalink to “一、LLM 基础”">​</a></h2><h3 id="_1-transformer-的核心结构是什么" tabindex="-1">1. Transformer 的核心结构是什么？ <a class="header-anchor" href="#_1-transformer-的核心结构是什么" aria-label="Permalink to “1. Transformer 的核心结构是什么？”">​</a></h3><p>回答要点：</p><ul><li>Transformer 由 Attention、FFN、残差连接、LayerNorm、位置编码等组成。</li><li>自注意力用于建模 token 之间的依赖关系。</li><li>Decoder-only 架构常用于 GPT 类自回归语言模型。</li><li>推理时按 token 逐步生成，依赖 KV Cache 降低重复计算。</li></ul><h3 id="_2-attention-的计算过程是什么" tabindex="-1">2. Attention 的计算过程是什么？ <a class="header-anchor" href="#_2-attention-的计算过程是什么" aria-label="Permalink to “2. Attention 的计算过程是什么？”">​</a></h3><p>公式：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Attention(Q, K, V) = softmax(QK^T / sqrt(d_k)) V</span></span></code></pre></div><p>解释：</p><ul><li><code>Q</code> 表示当前位置要查询什么。</li><li><code>K</code> 表示每个 token 可以被匹配的特征。</li><li><code>V</code> 表示被聚合的信息。</li><li><code>softmax(QK^T)</code> 得到注意力权重。</li></ul><h3 id="_3-为什么-llm-推理会慢" tabindex="-1">3. 为什么 LLM 推理会慢？ <a class="header-anchor" href="#_3-为什么-llm-推理会慢" aria-label="Permalink to “3. 为什么 LLM 推理会慢？”">​</a></h3><p>主要瓶颈：</p><ul><li>自回归生成必须逐 token 串行。</li><li>长上下文导致 Attention 计算和 KV Cache 占用变大。</li><li>大模型参数量大，显存和内存带宽压力高。</li><li>工具调用、RAG、网络请求会引入额外链路延迟。</li></ul><p>优化方向：</p><ul><li>KV Cache、PagedAttention、FlashAttention。</li><li>量化、蒸馏、小模型路由。</li><li>Prompt 压缩、上下文裁剪。</li><li>流式输出、异步工具调用、缓存。</li></ul><h3 id="_4-temperature、top-p、top-k-分别影响什么" tabindex="-1">4. Temperature、Top-p、Top-k 分别影响什么？ <a class="header-anchor" href="#_4-temperature、top-p、top-k-分别影响什么" aria-label="Permalink to “4. Temperature、Top-p、Top-k 分别影响什么？”">​</a></h3><ul><li><code>temperature</code>：控制概率分布平滑程度，越高越随机。</li><li><code>top-p</code>：从累计概率达到 p 的候选 token 中采样。</li><li><code>top-k</code>：只从概率最高的 k 个 token 中采样。</li><li>面向严肃问答、工具调用、代码生成时通常降低随机性。</li></ul><h3 id="_5-function-calling-tool-calling-本质是什么" tabindex="-1">5. Function Calling / Tool Calling 本质是什么？ <a class="header-anchor" href="#_5-function-calling-tool-calling-本质是什么" aria-label="Permalink to “5. Function Calling / Tool Calling 本质是什么？”">​</a></h3><p>本质是让模型按约定 schema 生成结构化调用参数，再由后端执行真实工具。</p><p>关键点：</p><ul><li>模型不直接调用工具，只生成工具名和参数。</li><li>后端负责参数校验、权限控制、执行、重试和结果注入。</li><li>工具结果需要再次放回上下文，让模型继续推理。</li></ul><h3 id="_6-embedding-是什么" tabindex="-1">6. Embedding 是什么？ <a class="header-anchor" href="#_6-embedding-是什么" aria-label="Permalink to “6. Embedding 是什么？”">​</a></h3><p>Embedding 是将文本映射到高维向量空间的表示。语义相近的文本向量距离更近，常用于 RAG 检索、聚类、去重、推荐等场景。</p><p>常见相似度：</p><ul><li>Cosine Similarity</li><li>Dot Product</li><li>Euclidean Distance</li></ul><h3 id="_7-fine-tuning、rag、prompt-engineering-如何选择" tabindex="-1">7. Fine-tuning、RAG、Prompt Engineering 如何选择？ <a class="header-anchor" href="#_7-fine-tuning、rag、prompt-engineering-如何选择" aria-label="Permalink to “7. Fine-tuning、RAG、Prompt Engineering 如何选择？”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>适合场景</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>Prompt</td><td>规则明确、轻量定制</td><td>成本低、迭代快</td><td>稳定性有限</td></tr><tr><td>RAG</td><td>需要外部知识、频繁更新</td><td>不改模型、知识可追溯</td><td>检索质量决定上限</td></tr><tr><td>Fine-tuning</td><td>风格、格式、领域能力固化</td><td>输出稳定、降低 prompt 复杂度</td><td>成本高、知识更新慢</td></tr></tbody></table><p>面试表达：优先 Prompt/RAG 解决知识和流程问题，只有当输出风格、格式、领域模式长期稳定且 prompt 难以约束时再考虑微调。</p><h2 id="二、llvm-基础" tabindex="-1">二、LLVM 基础 <a class="header-anchor" href="#二、llvm-基础" aria-label="Permalink to “二、LLVM 基础”">​</a></h2><h3 id="_1-llvm-是什么" tabindex="-1">1. LLVM 是什么？ <a class="header-anchor" href="#_1-llvm-是什么" aria-label="Permalink to “1. LLVM 是什么？”">​</a></h3><p>LLVM 是一套模块化编译器基础设施，包含前端、中间表示 IR、优化器和后端代码生成能力。</p><p>典型链路：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Source Code -&gt; Frontend -&gt; LLVM IR -&gt; Optimizer -&gt; Backend -&gt; Machine Code</span></span></code></pre></div><h3 id="_2-llvm-ir-的特点是什么" tabindex="-1">2. LLVM IR 的特点是什么？ <a class="header-anchor" href="#_2-llvm-ir-的特点是什么" aria-label="Permalink to “2. LLVM IR 的特点是什么？”">​</a></h3><ul><li>静态单赋值 SSA 形式。</li><li>与源语言无关，便于跨语言优化。</li><li>类型明确，适合做中间层分析与优化。</li><li>可读文本格式 <code>.ll</code> 与 bitcode 格式 <code>.bc</code>。</li></ul><h3 id="_3-pass-是什么" tabindex="-1">3. Pass 是什么？ <a class="header-anchor" href="#_3-pass-是什么" aria-label="Permalink to “3. Pass 是什么？”">​</a></h3><p>Pass 是 LLVM 中的分析或优化单元。</p><p>常见 Pass：</p><ul><li>常量传播</li><li>死代码删除</li><li>循环优化</li><li>函数内联</li><li>指令合并</li></ul><h3 id="_4-jit-和-aot-的区别" tabindex="-1">4. JIT 和 AOT 的区别？ <a class="header-anchor" href="#_4-jit-和-aot-的区别" aria-label="Permalink to “4. JIT 和 AOT 的区别？”">​</a></h3><ul><li>AOT：提前编译，运行时直接执行机器码，启动快、部署稳定。</li><li>JIT：运行时编译，可利用运行时信息优化，但有编译开销。</li></ul><p>AI Infra 中可能用 LLVM/MLIR 做模型算子编译、图优化和硬件后端适配。</p><h3 id="_5-llvm-和-agent-后端有什么关系" tabindex="-1">5. LLVM 和 Agent 后端有什么关系？ <a class="header-anchor" href="#_5-llvm-和-agent-后端有什么关系" aria-label="Permalink to “5. LLVM 和 Agent 后端有什么关系？”">​</a></h3><p>一般业务 Agent 后端不会直接使用 LLVM。但在以下场景可能相关：</p><ul><li>模型推理引擎优化。</li><li>DSL 或代码生成 Agent。</li><li>沙箱执行、代码分析、编译诊断 Agent。</li><li>AI 编译器、算子优化、MLIR 相关岗位。</li></ul>',46)])])}const g=a(n,[["render",r]]);export{m as __pageData,g as default};
